const p = $json;

// Age is a string and often empty — parse defensively
const ageNum = p.Age === '' || p.Age === null ? null : Number(p.Age);

let ageBracket;
if (ageNum === null)      ageBracket = 'Unknown';
else if (ageNum < 13)     ageBracket = 'Child';
else if (ageNum < 20)     ageBracket = 'Teen';
else if (ageNum < 60)     ageBracket = 'Adult';
else                      ageBracket = 'Senior';

// "Braund, Mr. Owen Harris" → title = "Mr"
const titleMatch = p.Name.match(/,\s*([^.]+)\./);
const title = titleMatch ? titleMatch[1].trim() : 'Unknown';

const classLabel = { '1': 'First', '2': 'Second', '3': 'Third' }[p.Pclass] || 'Unknown';

return {
  json: {
    passengerId: Number(p.PassengerId),
    name: p.Name,
    title,
    sex: p.Sex,
    age: ageNum,
    ageBracket,
    pclass: Number(p.Pclass),
    classLabel,
    fare: Number(p.Fare),
    survived: p.Survived === '1' || p.Survived === 1,
    familySize: Number(p.SibSp) + Number(p.Parch) + 1
  }
};

const rows = $input.all().map(i => i.json);

const groups = {};
for (const r of rows) {
  const key = r.classLabel;
  if (!groups[key]) {
    groups[key] = { classLabel: key, pclass: r.pclass, total: 0, survivors: 0, fares: [], ages: [] };
  }
  groups[key].total++;
  if (r.survived) groups[key].survivors++;
  if (!isNaN(r.fare)) groups[key].fares.push(r.fare);
  if (r.age !== null) groups[key].ages.push(r.age);
}

const avg = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null;

return Object.values(groups)
  .sort((a, b) => a.pclass - b.pclass)
  .map(g => ({
    json: {
      class: g.classLabel,
      passengers: g.total,
      survivors: g.survivors,
      survivalRate: Number(((g.survivors / g.total) * 100).toFixed(1)),
      avgFare: Number(avg(g.fares).toFixed(2)),
      avgAge: g.ages.length ? Number(avg(g.ages).toFixed(1)) : null,
      ageDataMissing: g.total - g.ages.length
    }
  }));
